#! bin/bash

# This script moves the .summary files generated by featureCounts into a separate sub-directory for clarity.

#Path to featureCounts data folder
featureCounts_path=../06_featureCounts

# List of featureCounts .txt.summary files
summary_files_list=$featureCounts_path/*.txt.summary

#Path to STAR log directory
summary_path=$featureCounts_path"/featureCounts_summary/"

#Checks if output featureCounts_summary directory exists and if not, makes one.
if [ ! -d "$summary_path" ]; then
    echo $summary_path does not exist! Creating one now.
    mkdir $summary_path
fi

mv -n $summary_files_list $summary_path